class JumpingNumbers {
  private List<Integer> res;
  private int n;

  private void visit(int num) {
    if (num >= n) {
      return;
    }
    res.add(num);
    int lastDigit = num % 10;
    if (lastDigit > 0) {
      visit(num * 10 + (lastDigit - 1));
    }
    if (lastDigit < 9) {
      visit(num * 10 + (lastDigit + 1));
    }
  }

  public List<Integer> solve(int n) {
    this.n = n;
    res = new ArrayList<>();
    for (int num = 1; num < 10; num++) {
      visit(num);
    }
    Collections.sort(res);
    return res;
  }
}

